// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ERC721ReceiverForwarder {
    // Minimal helper that calls onERC721Received and forwards the returned bytes4
    function forwardOnERC721Received(
        address target,
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external returns (bytes4) {
        (bool success, bytes memory ret) = target.call(
            abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", operator, from, tokenId, data)
        );
        require(success, "forward failed");
        return abi.decode(ret, (bytes4));
    }
}

contract InvMutTest is Test {
    C c;
    ERC721ReceiverForwarder forwarder;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
        forwarder = new ERC721ReceiverForwarder();
    }

    function testFuzz_property(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) public {
        // The fuzzer can choose any inputs; we only ensure the call does not revert.
        // The reference implementation returns ERC721TokenReceiver.onERC721Received.selector,
        // while the buggy one returns 0x00000000.
        bytes4 returned = forwarder.forwardOnERC721Received(address(c), operator, from, tokenId, data);
        assertTrue(returned == 0x150b7a02); // ERC721TokenReceiver.onERC721Received.selector
    }
}

