// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee) public {
        // Restrict _changeFee to a valid range if necessary, but keep it wide
        // No vm.assume needed here since any uint56 is valid
        c.initialize(
            address(0),
            address(0),
            1000,
            1000,
            _changeFee,
            500, // feeRate <= 5000
            bytes32(0),
            false,
            false
        );
        // The rule: after a single successful call to initialize,
        // the changeFee getter must return the _changeFee argument.
        // The mutant writes changeFee after setting initialized=true,
        // which has no effect on the second call (it reverts) but in the
        // first call the storage write is overwritten, so changeFee remains 0.
        assertEq(c.changeFee(), _changeFee);
    }
}
